ENTRY_POINT_OF_LAKE_LEVEL:
	call INIT_VIDEO_BUFFERS
	load id=0x0010
	load id=0x0008
	load id=0x0051
	load id=0x0030
	load id=0x0031
	load id=0x0032
	load id=0x0035
	load id=0x0039
